# Generated by build.py from recipe.yml for recipe imap-test-a-shared-team-folder. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'notice.eml'), "From: app@example.com`r`nTo: team@example.com`r`nSubject: Server maintenance tonight`r`n`r`nThe build server is down from 22:00.`r`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', '--mailbox', 'carol@example.com:carolpass', '--shared-folder', 'team=ann@example.com,bob@example.com', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -u ann@example.com:annpass -T notice.eml imap://127.0.0.1:8081/Shared/team --next -u bob@example.com:bobpass -X "STORE 1 +FLAGS (\Flagged)" imap://127.0.0.1:8081/Shared/team --next -u ann@example.com:annpass "imap://127.0.0.1:8081/Shared/team?FLAGGED" } finally { Stop-Process $server0 }
